SELECT
    B.bug_id,
    B.title,
    B.description,
    B.status,
    U.username AS assigned_to_username,
    U.email AS assigned_to_email
FROM
    Bugs AS B
JOIN
    Users AS U ON B.assigned_to_user_id = U.user_id;

SELECT
    bug_id,
    title,
    description,
    status
FROM
    Bugs
WHERE
    status = 'Open';

SELECT
    U.username,
    COUNT(B.bug_id) AS bug_count
FROM
    Users AS U
JOIN
    Bugs AS B ON U.user_id = B.assigned_to_user_id
GROUP BY
    U.username;

INSERT INTO Bugs (title, description, status, assigned_to_user_id)
VALUES ('New Bug Title', 'Detailed description of the new bug.', 'New', 1);

UPDATE Bugs
SET status = 'Closed'
WHERE bug_id = 1;

SELECT B.bug_id, B.title, B.status FROM Bugs AS B JOIN Users AS U ON B.assigned_to_user_id = U.user_id WHERE U.username = 'alice';
SELECT U.user_id, U.username, B.title FROM Users AS U JOIN Bugs AS B ON U.user_id = B.assigned_to_user_id WHERE B.status = 'New';
SELECT B.title, B.status, U.email FROM Bugs AS B JOIN Users AS U ON B.assigned_to_user_id = U.user_id WHERE B.bug_id = 2;

SELECT U.username, U.email FROM Users AS U JOIN Bugs AS B ON U.user_id = B.assigned_to_user_id GROUP BY U.username, U.email HAVING COUNT(B.bug_id) > 1;

SELECT B.bug_id, B.title, U.username FROM Bugs AS B JOIN Users AS U ON B.assigned_to_user_id = U.user_id WHERE B.description LIKE '%error%';

SELECT U.username, U.user_id FROM Users AS U JOIN Bugs AS B ON U.user_id = B.assigned_to_user_id WHERE B.status = 'Open' ORDER BY U.username;

SELECT B.title, U.username FROM Bugs AS B JOIN Users AS U ON B.assigned_to_user_id = U.user_id WHERE U.username = 'bob';

SELECT B.bug_id, B.status, U.username FROM Bugs AS B JOIN Users AS U ON B.assigned_to_user_id = U.user_id WHERE B.status IN ('Open', 'Reopened');

