-- 1. List all vendors and their primary contacts.
SELECT V.vendor_name, C.first_name, C.last_name
FROM Vendors AS V
JOIN Contacts AS C ON V.vendor_id = C.vendor_id
WHERE C.role = 'Sales Manager' OR C.role = 'CEO' OR C.role = 'CTO';

-- 2. Find all contacts for a specific vendor (e.g., vendor_name = 'ABC Supplies').
SELECT C.first_name, C.last_name, C.email
FROM Contacts AS C
JOIN Vendors AS V ON C.vendor_id = V.vendor_id
WHERE V.vendor_name = 'ABC Supplies';

-- 3. Count the number of contacts per industry.
SELECT V.industry, COUNT(C.contact_id) AS NumberOfContacts
FROM Vendors AS V
JOIN Contacts AS C ON V.vendor_id = C.vendor_id
GROUP BY V.industry;

