SELECT
    S.FirstName,
    S.LastName
FROM
    Students AS S
JOIN
    Enrollments AS E ON S.StudentID = E.StudentID
JOIN
    Courses AS C ON E.CourseID = C.CourseID
WHERE
    C.CourseName = 'Calculus I' AND E.Grade = 'A';

SELECT
    S.FirstName,
    S.LastName,
    SUM(C.Credits) AS TotalCredits
FROM
    Students AS S
JOIN
    Enrollments AS E ON S.StudentID = E.StudentID
JOIN
    Courses AS C ON E.CourseID = C.CourseID
GROUP BY
    S.StudentID, S.FirstName, S.LastName;

SELECT
    C.CourseName,
    AVG(CASE E.Grade WHEN 'A' THEN 4 WHEN 'B' THEN 3 WHEN 'C' THEN 2 WHEN 'D' THEN 1 ELSE 0 END) AS AverageGrade
FROM
    Courses AS C
JOIN
    Enrollments AS E ON C.CourseID = E.CourseID
GROUP BY
    C.CourseName;

