    SP.salesperson_name,
    SUM(S.sale_amount) AS total_sales_amount
FROM Sales S
JOIN Salespeople SP ON S.salesperson_id = SP.salesperson_id
GROUP BY SP.salesperson_name
ORDER BY total_sales_amount DESC
LIMIT 5;

SELECT R.region_name
FROM Regions R
LEFT JOIN (SELECT SP.region_id, SUM(S.sale_amount) AS region_total_sales
           FROM Sales S
           JOIN Salespeople SP ON S.salesperson_id = SP.salesperson_id
           GROUP BY SP.region_id) AS RegionalSales
ON R.region_id = RegionalSales.region_id
WHERE COALESCE(RegionalSales.region_total_sales, 0) < 1000;

