-- 1. Get the total data used by a specific subscription in a month.
SELECT SUM(ur.data_used_gb) AS total_data_used
FROM UsageRecords AS ur
JOIN Subscriptions AS s ON ur.sub_id = s.sub_id
WHERE s.sub_id = 101 AND ur.usage_date BETWEEN '2023-01-01' AND '2023-01-31';

-- 2. List all subscriptions on a particular plan.
SELECT s.sub_id, s.user_id, p.plan_name
FROM Subscriptions AS s
JOIN Plans AS p ON s.plan_id = p.plan_id
WHERE p.plan_name = 'Premium Plan';

-- 3. Record new data usage for a subscription. (INSERT statement, no JOIN needed)
INSERT INTO UsageRecords (sub_id, usage_date, data_used_gb)
VALUES (102, '2023-03-15', 5.5);

-- 4. Find subscriptions that have exceeded their data limit.
SELECT s.sub_id, s.user_id, p.plan_name, p.data_limit_gb, SUM(ur.data_used_gb) AS total_usage_current_month
FROM Subscriptions AS s
JOIN Plans AS p ON s.plan_id = p.plan_id
JOIN UsageRecords AS ur ON s.sub_id = ur.sub_id
WHERE ur.usage_date BETWEEN '2023-03-01' AND '2023-03-31'
GROUP BY s.sub_id, s.user_id, p.plan_name, p.data_limit_gb
HAVING SUM(ur.data_used_gb) > p.data_limit_gb;

-- 5. Calculate the remaining data limit for each active subscription.
SELECT s.sub_id, s.user_id, p.plan_name, p.data_limit_gb - COALESCE(SUM(ur.data_used_gb), 0) AS remaining_data_gb
FROM Subscriptions AS s
JOIN Plans AS p ON s.plan_id = p.plan_id
LEFT JOIN UsageRecords AS ur ON s.sub_id = ur.sub_id
WHERE s.end_date >= CURRENT_DATE AND ur.usage_date BETWEEN '2023-03-01' AND '2023-03-31'
GROUP BY s.sub_id, s.user_id, p.plan_name, p.data_limit_gb;

-- Additional queries with exactly ONE join:
SELECT s.sub_id, s.start_date FROM Subscriptions AS s JOIN Plans AS p ON s.plan_id = p.plan_id WHERE p.monthly_cost > 50;
SELECT p.plan_name, p.monthly_cost FROM Plans AS p JOIN Subscriptions AS s ON p.plan_id = s.plan_id GROUP BY p.plan_name, p.monthly_cost;
SELECT ur.usage_id, ur.data_used_gb FROM UsageRecords AS ur JOIN Subscriptions AS s ON ur.sub_id = s.sub_id WHERE s.user_id = 505;
SELECT s.user_id, COUNT(s.sub_id) FROM Subscriptions AS s JOIN Plans AS p ON s.plan_id = p.plan_id GROUP BY s.user_id;
SELECT p.plan_name, AVG(p.data_limit_gb) FROM Plans AS p JOIN Subscriptions AS s ON p.plan_id = s.plan_id GROUP BY p.plan_name;
SELECT ur.usage_date, SUM(ur.data_used_gb) FROM UsageRecords AS ur JOIN Subscriptions AS s ON ur.sub_id = s.sub_id GROUP BY ur.usage_date;
SELECT s.sub_id FROM Subscriptions AS s JOIN UsageRecords AS ur ON s.sub_id = ur.sub_id WHERE ur.data_used_gb > 10;
SELECT p.plan_name FROM Plans AS p JOIN Subscriptions AS s ON p.plan_id = s.plan_id WHERE s.start_date < '2023-01-01';

