INSERT INTO Reviews (review_id, customer_id, product_id, rating, comment, review_date) VALUES (3, 1, 102, 5, 'Great mouse!', '2023-01-17');

-- 1. Find all reviews for a specific product with a rating of 5.
SELECT R.review_id, R.comment, R.rating
FROM Reviews AS R
JOIN Products AS P ON R.product_id = P.product_id
WHERE P.name = 'Laptop' AND R.rating = 5;

-- 2. List all reviews written by a particular customer.
SELECT R.review_id, P.name AS product_name, R.rating, R.comment
FROM Reviews AS R
JOIN Customers AS C ON R.customer_id = C.customer_id
JOIN Products AS P ON R.product_id = P.product_id
WHERE C.name = 'Alice';

-- Single JOIN examples
SELECT C.name, R.comment
FROM Reviews AS R
JOIN Customers AS C ON R.customer_id = C.customer_id;

SELECT P.name, R.rating
FROM Reviews AS R
JOIN Products AS P ON R.product_id = P.product_id;

-- 3. Submit a new product review.
INSERT INTO Reviews (review_id, customer_id, product_id, rating, comment, review_date) VALUES (4, 2, 102, 3, 'Decent mouse.', '2023-01-18');

-- 4. Update the comment of an existing review.
UPDATE Reviews SET comment = 'Absolutely fantastic laptop!' WHERE review_id = 1;

-- 5. Calculate the average rating for each brand.
SELECT P.brand, AVG(R.rating) AS average_rating
FROM Reviews AS R
JOIN Products AS P ON R.product_id = P.product_id
GROUP BY P.brand;

SELECT C.name, R.review_date
FROM Customers AS C
JOIN Reviews AS R ON C.customer_id = R.customer_id;

